'use client'

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'

/**
 * EmptyState, 1:1 with the uiKit `EmptyState` set (852:51897) and its `_buttonGroup`
 * (852:51922): a centred column 350 wide (320–560), padding 16 / 16 / 20, 16 apart, radius-2xl.
 *
 * - icon: a 16px glyph in text/default on a bg/muted tile, 10 padding, radius-lg (36 square).
 * - title in text/lg medium (16/24), description in Body/lg (14/21) text/muted, 8 apart, centred.
 * - actions: a row of Buttons 8 apart: Primary + Secondary, Secondary alone, or a Tertiary
 *   "Learn more" with a trailing arrow. Pass them as `<Button>` elements.
 * - border: ghost (none), dashed or outline, both 1px border/default.
 */
const emptyStateVariants = cva(
  'sa:flex sa:w-[350px] sa:max-w-[560px] sa:min-w-[min(320px,100%)] sa:flex-col sa:items-center sa:gap-4 sa:rounded-2xl sa:px-4 sa:pt-4 sa:pb-5 sa:text-center',
  {
    variants: {
      border: {
        ghost: '',
        dashed: 'sa:border sa:border-dashed sa:border-border-default',
        outline: 'sa:border sa:border-border-default',
      },
    },
    defaultVariants: { border: 'ghost' },
  },
)

export interface EmptyStateProps
  extends Omit<React.ComponentProps<'div'>, 'title'>,
    VariantProps<typeof emptyStateVariants> {
  title: React.ReactNode
  description?: React.ReactNode
  /** A 16px icon, e.g. from iconoir-react. */
  icon?: React.ReactNode
  /** One or two Buttons. */
  actions?: React.ReactNode
}

export function EmptyState({ className, border, title, description, icon, actions, ...props }: EmptyStateProps) {
  return (
    <div data-slot="empty-state" className={cn(emptyStateVariants({ border }), className)} {...props}>
      {icon && (
        <div
          aria-hidden
          className="sa:flex sa:shrink-0 sa:items-center sa:justify-center sa:rounded-lg sa:bg-bg-muted sa:p-2.5 sa:text-text-default sa:[&_svg]:size-4 sa:[&_svg]:[stroke-width:1.875]"
        >
          {icon}
        </div>
      )}
      <div className="sa:flex sa:w-full sa:flex-col sa:items-center sa:gap-2">
        <p className="sa:w-full sa:text-lg sa:font-medium sa:text-text-default">{title}</p>
        {description && <p className="sa:w-full sa:text-body-lg sa:text-text-muted">{description}</p>}
      </div>
      {actions && <div className="sa:flex sa:flex-wrap sa:items-start sa:justify-center sa:gap-2">{actions}</div>}
    </div>
  )
}

export { emptyStateVariants }
